  ($t$Tyrannosaure$t$, $t$Tyrannosaurus Rex$t$, $t$Très grande$t$, $t$Bête$t$, $t$sans alignement$t$, 13, $t$armure naturelle$t$, 136, $t$13d12 + 52$t$, $t${"walk":50}$t$::jsonb, $t${"str":25,"dex":10,"con":19,"int":2,"wis":12,"cha":9}$t$::jsonb, $t${"str":10,"wis":4}$t$::jsonb, $t${"Perception":4}$t$::jsonb, null, null, null, null, $t$Perception passive 14$t$, $t$aucune$t$, 8, 3900, 3, 3, $t$[]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"Le tyrannosaure effectue une attaque de Morsure et une attaque de Queue."},{"name":"Morsure","description":"Jet d'attaque au corps à corps : +10, allonge 3 m. 33 (4d12 + 7) dégâts perforants. Si la cible est une créature de taille G ou inférieure, elle subit l'état agrippé (évasion DD 17). Tant qu'elle est agrippée, la cible subit l'état entravé et ne peut pas être ciblée par la Queue du tyrannosaure."},{"name":"Queue","description":"Jet d'attaque au corps à corps : +10, allonge 4,50 m. 25 (4d8 + 7) dégâts contondants. Si la cible est une créature de taille TG ou inférieure, elle subit l'état à terre."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb),
  ($t$Licorne$t$, $t$Unicorn$t$, $t$Grande$t$, $t$Céleste$t$, $t$loyal bon$t$, 12, $t$armure naturelle$t$, 97, $t$13d10 + 26$t$, $t${"walk":50}$t$::jsonb, $t${"str":18,"dex":14,"con":15,"int":11,"wis":17,"cha":16}$t$::jsonb, $t${}$t$::jsonb, $t${}$t$::jsonb, null, null, $t$poison$t$, $t$charmé, paralysé, empoisonné$t$, $t$vision dans le noir 18 m, Perception passive 13$t$, $t$céleste, elfique, sylvestre; télépathie 36 m$t$, 5, 1800, 3, 8, $t$[{"name":"Résistance légendaire (3/jour)","description":"Si la licorne rate un jet de sauvegarde, elle peut choisir de le réussir à la place."},{"name":"Résistance à la magie","description":"La licorne a l'avantage aux jets de sauvegarde contre les sorts et autres effets magiques."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"La licorne effectue une attaque de Sabots et une attaque de Corne radieuse."},{"name":"Sabots","description":"Jet d'attaque au corps à corps : +7, allonge 1,50 m. 11 (2d6 + 4) dégâts contondants."},{"name":"Corne radieuse","description":"Jet d'attaque au corps à corps : +7, allonge 1,50 m. 9 (1d10 + 4) dégâts radiants."},{"name":"Incantation","description":"La licorne lance l'un des sorts suivants, sans composantes et en utilisant le Charisme comme caractéristique d'incantation (DD de sauvegarde des sorts 14). À volonté : Détection du mal et du bien, Druidisme. 1/jour chacun : Apaisement des émotions, Dissipation du mal et du bien, Enchevêtrement, Mot de rappel, Passage sans trace."}]$t$::jsonb, $t$[{"name":"Bénédiction de la licorne (3/jour)","description":"La licorne touche une autre créature de sa corne et lance sur elle Soin des blessures ou Restauration partielle, en utilisant la même caractéristique d'incantation que pour Incantation."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[{"name":"Corne chargeante","description":"La licorne se déplace d'une distance maximale égale à la moitié de sa vitesse sans provoquer d'attaque d'opportunité, puis effectue une attaque de Corne radieuse."},{"name":"Bouclier chatoyant","description":"La licorne cible elle-même ou une créature qu'elle peut voir à 18 m ou moins. La cible gagne 10 (3d6) points de vie temporaires, et sa CA augmente de 2 jusqu'à la fin du prochain tour de la licorne. La licorne ne peut pas réutiliser cette action avant le début de son prochain tour."}]$t$::jsonb),
  ($t$Vampire$t$, $t$Vampire$t$, $t$Petite$t$, $t$Mort-vivant$t$, $t$loyal mauvais$t$, 16, $t$armure naturelle$t$, 195, $t$23d8 + 92$t$, $t${"walk":40,"climb":40}$t$::jsonb, $t${"str":18,"dex":18,"con":18,"int":17,"wis":15,"cha":18}$t$::jsonb, $t${"dex":9,"con":9,"wis":7,"cha":9}$t$::jsonb, $t${"Perception":7,"Discrétion":9}$t$::jsonb, null, $t$nécrotique$t$, null, null, $t$vision dans le noir 36 m, Perception passive 17$t$, $t$commun et deux autres langues$t$, 13, 10000, 5, 14, $t$[{"name":"Résistance légendaire (3/jour, ou 4/jour dans son antre)","description":"Si le vampire rate un jet de sauvegarde, il peut choisir de le réussir à la place."},{"name":"Fuite brumeuse","description":"Si le vampire tombe à 0 point de vie hors de son lieu de repos, il utilise Métamorphose pour se changer en brume (aucune action requise). S'il ne peut pas utiliser Métamorphose, il est détruit. Tant qu'il a 0 point de vie sous forme de brume, il ne peut pas reprendre sa forme de vampire et doit atteindre son lieu de repos dans les 2 heures, sans quoi il est détruit. Une fois dans son lieu de repos, il reprend sa forme de vampire et subit l'état paralysé jusqu'à ce qu'il récupère des points de vie ; il récupère 1 point de vie après y avoir passé 1 heure."},{"name":"Pattes d'araignée","description":"Le vampire peut escalader les surfaces difficiles, y compris au plafond, sans avoir à faire de test de caractéristique."},{"name":"Faiblesses du vampire","description":"Le vampire a les faiblesses suivantes. Interdiction : le vampire ne peut pas entrer dans une résidence sans l'invitation d'un de ses occupants. Eau courante : le vampire subit 20 dégâts d'acide s'il termine son tour dans de l'eau courante. Pieu dans le cœur : si une arme infligeant des dégâts perforants est enfoncée dans le cœur du vampire alors qu'il subit l'état neutralisé dans son lieu de repos, il subit l'état paralysé jusqu'à ce que l'arme soit retirée. Lumière du soleil : le vampire subit 20 dégâts radiants s'il commence son tour au soleil. Au soleil, il a le désavantage aux jets d'attaque et aux tests de caractéristique."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"Le vampire effectue deux attaques de Frappe d'outre-tombe et utilise Morsure."},{"name":"Frappe d'outre-tombe","description":"Jet d'attaque au corps à corps : +9, allonge 1,50 m. 8 (1d8 + 4) dégâts contondants plus 7 (2d6) dégâts nécrotiques. Si la cible est une créature de taille G ou inférieure, elle subit l'état agrippé (évasion DD 14) par l'une de ses deux mains."},{"name":"Morsure","description":"Jet de sauvegarde de Constitution : DD 17, une créature à 1,50 m ou moins, consentante ou subissant l'état agrippé, neutralisé ou entravé. Échec : 6 (1d4 + 4) dégâts perforants plus 13 (3d8) dégâts nécrotiques. Le maximum de points de vie de la cible diminue d'un montant égal aux dégâts nécrotiques subis, et le vampire récupère autant de points de vie. Un humanoïde réduit à 0 point de vie par ces dégâts puis enterré se relève au coucher du soleil suivant sous la forme d'un rejeton vampirique contrôlé par le vampire."}]$t$::jsonb, $t$[{"name":"Métamorphose","description":"S'il n'est ni au soleil ni dans de l'eau courante, le vampire se métamorphose en chauve-souris de taille TP (vitesse 1,50 m, vol 9 m) ou en nuage de brume de taille M (vitesse 1,50 m, vol 6 m, vol stationnaire), ou reprend sa forme de vampire. Ce qu'il porte se transforme avec lui. Sous forme de chauve-souris, il ne peut pas parler ; ses statistiques de jeu, hormis sa taille et sa vitesse, sont inchangées. Sous forme de brume, il ne peut effectuer aucune action, parler ni manipuler d'objets. Il est sans poids et peut entrer dans l'espace d'un ennemi et s'y arrêter. Il peut passer partout où l'air passe, mais pas à travers un liquide. Il a la résistance à tous les dégâts, sauf ceux infligés par la lumière du soleil."},{"name":"Charme (recharge 5-6)","description":"Le vampire lance Charme-personne, sans composantes et en utilisant le Charisme comme caractéristique d'incantation (DD de sauvegarde des sorts 17), et la durée est de 24 heures. La cible charmée accepte volontiers la Morsure du vampire, dont les dégâts ne mettent pas fin au sort. Quand le sort prend fin, la cible ignore avoir été charmée par le vampire."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[{"name":"Frappe immortelle","description":"Le vampire se déplace d'une distance maximale égale à la moitié de sa vitesse et effectue une attaque de Frappe d'outre-tombe."},{"name":"Envoûtement","description":"Le vampire lance Injonction, sans composantes et en utilisant le Charisme comme caractéristique d'incantation (DD de sauvegarde des sorts 17). Le vampire ne peut pas réutiliser cette action avant le début de son prochain tour."}]$t$::jsonb),
  ($t$Familier vampirique$t$, $t$Vampire Familiar$t$, $t$Petite$t$, $t$Humanoïde$t$, $t$neutre mauvais$t$, 15, $t$armure naturelle$t$, 65, $t$10d8 + 20$t$, $t${"walk":30,"climb":30}$t$::jsonb, $t${"str":17,"dex":16,"con":15,"int":10,"wis":10,"cha":14}$t$::jsonb, $t${"dex":5,"wis":2}$t$::jsonb, $t${"Perception":4,"Persuasion":4,"Discrétion":7}$t$::jsonb, null, $t$nécrotique$t$, null, null, $t$vision dans le noir 18 m, Perception passive 14$t$, $t$commun et une autre langue$t$, 3, 700, 2, 5, $t$[{"name":"Lien vampirique","description":"Tant que le familier et son maître vampire se trouvent sur le même plan d'existence, le vampire peut communiquer par télépathie avec le familier et percevoir à travers ses sens."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"Le familier effectue deux attaques de Dague ombrale."},{"name":"Dague ombrale","description":"Jet d'attaque au corps à corps ou à distance : +5, allonge 1,50 m ou portée 6/18 m. 5 (1d4 + 3) dégâts perforants plus 7 (3d4) dégâts nécrotiques. Si la cible est réduite à 0 point de vie par cette attaque, elle est stabilisée mais subit l'état empoisonné pendant 1 heure. Tant qu'elle est empoisonnée, elle subit l'état paralysé."}]$t$::jsonb, $t$[{"name":"Agilité immortelle","description":"Le familier effectue l'action Foncer ou Se désengager."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb),
