  ($t$Vrock$t$, $t$Vrock$t$, $t$Grande$t$, $t$Fiélon$t$, $t$chaotique mauvais$t$, 15, $t$armure naturelle$t$, 152, $t$16d10 + 64$t$, $t${"walk":40,"fly":60}$t$::jsonb, $t${"str":17,"dex":15,"con":18,"int":8,"wis":13,"cha":8}$t$::jsonb, $t${"dex":5,"wis":4,"cha":2}$t$::jsonb, $t${}$t$::jsonb, null, $t$froid, feu, foudre$t$, $t$poison$t$, $t$empoisonné$t$, $t$vision dans le noir 36 m, Perception passive 11$t$, $t$abyssal; télépathie 36 m$t$, 6, 2300, 3, 2, $t$[{"name":"Restauration démoniaque","description":"Si le vrock meurt hors des Abysses, son corps se dissout en ichor et il obtient instantanément un nouveau corps, revenant à la vie avec tous ses points de vie quelque part dans les Abysses."},{"name":"Résistance à la magie","description":"Le vrock a l'avantage aux jets de sauvegarde contre les sorts et autres effets magiques."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"Le vrock effectue deux attaques de Déchiquetage."},{"name":"Déchiquetage","description":"Jet d'attaque au corps à corps : +6, allonge 1,50 m. 10 (2d6 + 3) dégâts perforants plus 10 (3d6) dégâts de poison."},{"name":"Spores (recharge 6)","description":"Jet de sauvegarde de Constitution : DD 15, chaque créature dans une émanation de 6 m centrée sur le vrock. Échec : la cible subit l'état empoisonné et refait le jet à la fin de chacun de ses tours, mettant fin à l'effet en cas de réussite. Tant qu'elle est empoisonnée, la cible subit 5 (1d10) dégâts de poison au début de chacun de ses tours. Vider une fiole d'eau bénite sur la cible met fin à l'effet."},{"name":"Cri étourdissant (1/jour)","description":"Jet de sauvegarde de Constitution : DD 15, chaque créature dans une émanation de 6 m centrée sur le vrock (les démons réussissent automatiquement). Échec : 10 (3d6) dégâts de tonnerre, et la cible subit l'état étourdi jusqu'à la fin du prochain tour du vrock."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb),
  ($t$Vautour$t$, $t$Vulture$t$, $t$Moyenne$t$, $t$Bête$t$, $t$sans alignement$t$, 10, $t$armure naturelle$t$, 5, $t$1d8 + 1$t$, $t${"walk":10,"fly":50}$t$::jsonb, $t${"str":7,"dex":10,"con":13,"int":2,"wis":12,"cha":4}$t$::jsonb, $t${}$t$::jsonb, $t${"Perception":3}$t$::jsonb, null, null, null, null, $t$Perception passive 13$t$, $t$aucune$t$, 0, 0, 2, 0, $t$[{"name":"Tactique de meute","description":"Le vautour a l'avantage à un jet d'attaque contre une créature si au moins un de ses alliés se trouve à 1,50 m ou moins de celle-ci et ne subit pas l'état neutralisé."}]$t$::jsonb, $t$[{"name":"Bec","description":"Jet d'attaque au corps à corps : +2, allonge 1,50 m. 2 (1d4) dégâts perforants."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb)
    ) as t(name_fr, name_en, size, ctype, alignment, ac, armor_detail, hp, hit_dice, speed, abilities, saves, skills, vuln, res, imm, cond_imm, senses, languages, cr, xp, pb, init, traits, actions, bonus_actions, reactions, legendary)
  loop
    if not exists (
      select 1 from public.translations tr
       where tr.entity_type = 'creature' and tr.field_name = 'name' and tr.locale = 'en' and tr.value = rec.name_en
    ) then
      insert into public.creatures (size, creature_type, alignment, armor_class, armor_detail, hit_points, hit_dice, speed,
                                    ability_scores, saving_throws, skills, damage_vulnerabilities, damage_resistances,
                                    damage_immunities, condition_immunities, senses, languages, challenge_rating,
                                    experience_points, proficiency_bonus, initiative_bonus, traits, actions, bonus_actions,
                                    reactions, legendary_actions, source)
        values (rec.size, rec.ctype, rec.alignment, rec.ac, rec.armor_detail, rec.hp, rec.hit_dice, rec.speed,
                rec.abilities, rec.saves, rec.skills, rec.vuln, rec.res, rec.imm, rec.cond_imm, rec.senses, rec.languages,
                rec.cr, rec.xp, rec.pb, rec.init, rec.traits, rec.actions, rec.bonus_actions, rec.reactions, rec.legendary,
                'SRD 5.2 (Manuel des Monstres 2024)')
        returning id into v_id;
      insert into public.translations (entity_type, entity_id, field_name, locale, value) values
        ('creature', v_id::text, 'name', 'fr', rec.name_fr),
        ('creature', v_id::text, 'name', 'en', rec.name_en);
      v_inserted := v_inserted + 1;
    end if;
  end loop;
  raise notice 'créatures insérées : %', v_inserted;
end $$;
